/** 判题脚手架：面板订阅与标签页的契约类型（测试与考生共用）。 */
export interface SocketMessage {
  readonly topic: string;
  readonly text: string;
}

export interface PanelSocket {
  connect(): void;
  close(): void;
  onMessage(handler: (message: SocketMessage) => void): void;
}

export type SocketFactory = (tabId: string) => PanelSocket;

export interface Tab {
  readonly id: string;
  readonly label: string;
}

import { act, fireEvent, render, screen } from '@testing-library/react';
import { expect, it } from 'vitest';
import type { SocketMessage } from './socketKit';
import { TabShell } from './Solution';

interface SocketRecord {
  tabId: string;
  connects: number;
  closes: number;
  handlers: ((message: SocketMessage) => void)[];
}

function makeBackends() {
  const sockets: SocketRecord[] = [];
  const created: Record<string, number> = {};
  const loaded: Record<string, number> = {};
  const createSocket = (tabId: string) => {
    created[tabId] = (created[tabId] ?? 0) + 1;
    const record: SocketRecord = { tabId, connects: 0, closes: 0, handlers: [] };
    sockets.push(record);
    return {
      connect() {
        record.connects += 1;
      },
      close() {
        record.closes += 1;
      },
      onMessage(handler: (message: SocketMessage) => void) {
        record.handlers.push(handler);
      },
    };
  };
  const loadInitial = (tabId: string) => {
    loaded[tabId] = (loaded[tabId] ?? 0) + 1;
    return [tabId + '-alpha', tabId + '-beta'];
  };
  const forTab = (tabId: string) => sockets.filter((s) => s.tabId === tabId);
  const emit = (tabId: string, message: SocketMessage) => {
    const list = forTab(tabId);
    const live = list[list.length - 1];
    act(() => {
      live.handlers.slice().forEach((handler) => handler(message));
    });
  };
  return { sockets, created, loaded, createSocket, loadInitial, forTab, emit };
}

const TABS = [{ id: 'a', label: 'A' }, { id: 'b', label: 'B' }, { id: 'c', label: 'C' }];

function mount(b: ReturnType<typeof makeBackends>, activeId = 'a', filter = '') {
  const shell = (id: string, f: string) => (
    <TabShell tabs={TABS} activeId={id} filter={f} createSocket={b.createSocket} loadInitial={b.loadInitial} />
  );
  const view = render(shell(activeId, filter));
  const go = (id: string, f = filter) => {
    view.rerender(shell(id, f));
  };
  const text = (testid: string) => screen.queryByTestId(testid)?.textContent ?? 'MISSING';
  return { view, go, text };
}

it('可见面板建连且隐藏面板不预连', () => {
  const b = makeBackends();
  const m = mount(b, 'a', '');
  expect(b.created.a).toBe(1);
  expect(b.forTab('a')[0].connects).toBe(1);
  expect(b.created.b).toBeUndefined();
  expect(b.loaded.a).toBe(1);
  expect(b.loaded.b).toBeUndefined();
  // Activity：DOM 留在文档里，但没有 Effect
  expect(screen.queryByTestId('note-b')).not.toBe(null);
  expect(m.text('items-b')).toBe('');
  expect(m.text('items-a')).toBe('a-alpha|a-beta');
});

it('切走关闭连接切回重连但初始数据只拉一次', () => {
  const b = makeBackends();
  const m = mount(b, 'a', '');
  m.go('b');
  expect(b.forTab('a')[0].closes).toBe(1);
  expect(b.created.b).toBe(1);
  m.go('a');
  expect(b.created.a).toBe(2);
  expect(b.forTab('a')[1].connects).toBe(1);
  expect(b.loaded.a).toBe(1);
  expect(m.text('items-a')).toBe('a-alpha|a-beta');
});

it('隐藏期间 textarea 内容不丢', () => {
  const b = makeBackends();
  const m = mount(b, 'a', '');
  fireEvent.change(screen.getByTestId('note-a'), { target: { value: '写了一半的草稿' } });
  expect(screen.getByTestId('note-a')).toHaveProperty('value', '写了一半的草稿');
  m.go('b');
  m.go('a');
  expect((screen.getByTestId('note-a') as HTMLTextAreaElement).value).toBe('写了一半的草稿');
});

it('filter 变化不重连但消息处理读到最新值', () => {
  const b = makeBackends();
  const m = mount(b, 'a', '');
  for (let i = 1; i <= 5; i += 1) m.go('a', 'x' + i);
  expect(b.created.a).toBe(1);
  expect(m.text('matched-a')).toBe('0');
  b.emit('a', { topic: 'log', text: 'nothing here' });
  expect(m.text('matched-a')).toBe('0');
  m.go('a', 'x5');
  b.emit('a', { topic: 'log', text: 'a x5 hit' });
  expect(m.text('matched-a')).toBe('1');
});

it('超大次数来回切换时建连与关闭严格配对', () => {
  const b = makeBackends();
  const m = mount(b, 'a', '');
  for (let i = 0; i < 30; i += 1) {
    m.go('b');
    m.go('a');
  }
  expect(b.created.a).toBe(31);
  expect(b.forTab('a').reduce((sum, s) => sum + s.closes, 0)).toBe(30);
  expect(b.forTab('a').reduce((sum, s) => sum + s.connects, 0)).toBe(31);
  expect(b.loaded.a).toBe(1);
});

it('无数据与无匹配消息都不增加计数', () => {
  const b = makeBackends();
  const m = mount(b, 'c', 'needle');
  expect(m.text('matched-c')).toBe('0');
  b.emit('c', { topic: 'log', text: 'no match at all' });
  expect(m.text('matched-c')).toBe('0');
  b.emit('c', { topic: 'log', text: 'has needle inside' });
  expect(m.text('matched-c')).toBe('1');
});

