import { Activity, useEffect, useEffectEvent, useRef, useState } from 'react';
import type { PanelSocket, SocketFactory, Tab } from './socketKit';

export interface TabShellProps {
  tabs: Tab[];
  activeId: string;
  filter: string;
  createSocket: SocketFactory;
  loadInitial: (tabId: string) => string[];
}

function Panel({ tabId, filter, createSocket, loadInitial }: Omit<TabShellProps, 'tabs' | 'activeId'>) {
  const [note, setNote] = useState('');
  const [items, setItems] = useState<string[]>([]);
  const [matched, setMatched] = useState(0);

  /**
   * useEffectEvent：事件语义的回调，永远读最新已提交的 filter，
   * 但 identity 不进依赖数组，所以订阅不会因为 filter 变化而重启。
   */
  const onMessage = useEffectEvent((message: { topic: string; text: string }) => {
    if (filter && message.text.includes(filter)) setMatched((n) => n + 1);
  });

  const loaded = useRef(false);

  useEffect(() => {
    // 首屏数据在 Effect 里拉（初次就 hidden 时不跑）；切回来时 state 被保活，靠 ref 不再重拉
    if (!loaded.current) {
      loaded.current = true;
      setItems(loadInitial(tabId));
    }
    let socket: PanelSocket | null = null;
    let disposed = false;
    socket = createSocket(tabId);
    socket.onMessage((message) => {
      if (!disposed) onMessage(message);
    });
    socket.connect();
    return () => {
      disposed = true;
      socket?.close();
    };
    // onMessage 是 useEffectEvent 的结果：identity 每帧都变，绝不进依赖数组
  }, [tabId, createSocket, loadInitial]);

  return (
    <section>
      <textarea data-testid={'note-' + tabId} value={note} onChange={(event) => setNote(event.target.value)} />
      <span data-testid={'items-' + tabId}>{items.join('|')}</span>
      <span data-testid={'matched-' + tabId}>{matched}</span>
    </section>
  );
}

export function TabShell({ tabs, activeId, filter, createSocket, loadInitial }: TabShellProps) {
  return (
    <div>
      {tabs.map((tab) => (
        <Activity key={tab.id} mode={tab.id === activeId ? 'visible' : 'hidden'}>
          <Panel
            tabId={tab.id}
            filter={filter}
            createSocket={createSocket}
            loadInitial={loadInitial}
          />
        </Activity>
      ))}
    </div>
  );
}

