import { useEffect, useRef, useState } from 'react';

export function TabShell({ tabs, activeId, filter, createSocket, loadInitial }) {
  return (
    <div>
      {tabs.map((tab) => (
        <div key={tab.id} style={tab.id === activeId ? undefined : { display: 'none' }}>
          {tab.id === activeId ? (
            <Panel
              tabId={tab.id}
              filter={filter}
              createSocket={createSocket}
              loadInitial={loadInitial}
            />
          ) : null}
        </div>
      ))}
    </div>
  );
}

function Panel({ tabId, filter, createSocket, loadInitial }) {
  const [note, setNote] = useState('');
  const [items, setItems] = useState<string[]>([]);
  const loaded = useRef(false);
  if (!loaded.current) {
    loaded.current = true;
    setItems(loadInitial(tabId));
  }
  const [matched, setMatched] = useState(0);

  useEffect(() => {
    const socket = createSocket(tabId);
    socket.onMessage((message) => {
      if (filter && message.text.includes(filter)) setMatched((n) => n + 1);
    });
    socket.connect();
    return () => socket.close();
  }, [tabId, filter, createSocket]);

  return (
    <section>
      <textarea data-testid={'note-' + tabId} value={note} onChange={(event) => setNote(event.target.value)} />
      <span data-testid={'items-' + tabId}>{items.join('|')}</span>
      <span data-testid={'matched-' + tabId}>{matched}</span>
    </section>
  );
}
